 return f'''<a class="skip" href="#main">{d['skip']}</a><header class="site-header"><div class="container nav-inner"><a href="index.html" aria-label="Geniva - {d['home']}">{brand()}</a><nav class="nav-links" id="navigation" aria-label="{d['footnav']}">{nav}<a href="contact.html"{' aria-current="page"' if page=='contact' else ''}>{d['nav'][3]}</a></nav><div class="nav-tools"><nav class="language" aria-label="{d['langlabel']}">{languages}</nav><a class="nav-contact" href="contact.html">{d['contact']} ↗</a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">{d['menu']}</button></div></div></header>'''
